import json,pathlib
p=pathlib.Path('.book-work/planetaryskyunderstandingthecolorsaboveus-v1-7d866fc6ab2a/translations/ro/full/chunks')
t={
't000029':'''Înțelegerea spectrului electromagnetic este esențială pentru explicarea comportamentului luminii în atmosferă. Lumina solară conține lungimi de undă diferite, împrăștiate în grade diferite pe măsură ce traversează aerul. Lungimile scurte, precum violetul și albastrul, interacționează mai mult cu particulele atmosferice, inclusiv moleculele de oxigen și azot, dând naștere împrăștierii Rayleigh. De aceea vedem cerul albastru: lumina cu lungime de undă scurtă este împrăștiată în toate direcțiile. Spectrul electromagnetic nu explică doar fenomene atmosferice, ci este important și pentru multe procese naturale și tehnologice. El stă la baza transmiterii semnalelor și arată cum energia solară influențează vremea și clima Pământului. Studiindu-l, oamenii de știință pot înțelege mai bine interacțiunea diferitelor tipuri de radiație cu materia, contribuind la progrese în comunicații, medicină și monitorizarea mediului.''',
't000030':'''Pe scurt, spectrul electromagnetic cuprinde multe tipuri de radiație, iar lumina vizibilă ocupă numai o mică parte. El explică atât culorile văzute pe cer, cât și numeroase alte fenomene din natură și tehnologie.''',
't000031':'''Felul în care lumina interacționează cu particulele atmosferice depinde în mare măsură de mărimea lor raportată la lungimea de undă. Interacțiunile se împart în trei categorii principale. Împrăștierea Rayleigh apare când particulele, cum sunt moleculele aerului, sunt mult mai mici decât lungimea de undă. Ea este principala cauză a cerului albastru, deoarece lungimile de undă scurte, albastre și violete, sunt împrăștiate mai mult decât cele lungi. Împrăștierea Mie apare când particulele au dimensiuni apropiate de lungimea de undă, cum se întâmplă cu praful, polenul și unii aerosoli. Spre deosebire de procesul Rayleigh, aceasta depinde mai puțin de lungimea de undă și poate face cerul să pară albicios sau încețoșat, mai ales în zone cu mult praf ori poluare. Împrăștierea neselectivă apare când particulele sunt mult mai mari decât lungimea de undă, precum picăturile de apă din nori.''',
't000032':'''Această împrăștiere afectează aproape egal toate lungimile de undă, făcând norii să pară albi sau gri. Împrăștierea Rayleigh domină în atmosfera terestră și dă cerului albastrul său caracteristic. Particulele mai mari pot însă modifica efectul, producând alte aspecte, precum pâcla sau cerul complet acoperit.''',
't000033':'Capitolul al patrulea — Variații ale culorii cerului',
't000034':'''Culoarea cerului variază în cursul zilei din mai multe motive. Poziția Soarelui se schimbă pe măsură ce Pământul se rotește, modificând drumul luminii prin atmosferă. Umiditatea, temperatura și prezența aerosolilor influențează și ele împrăștierea și absorbția luminii. Geografia locală — munți, întinderi de apă și zone urbane — afectează condițiile atmosferice din apropiere. Anotimpul schimbă, de asemenea, traseul Soarelui și starea atmosferei. Cerul oferă unele dintre cele mai impresionante priveliști la răsărit și apus, dar și odată cu trecerea anotimpurilor. Aceste fenomene arată caracterul dinamic al atmosferei și interacțiunea ei cu lumina solară. Răsăriturile și apusurile aduc game spectaculoase de culori, de la roșu și portocaliu intens până la roz și violet delicat.''',
't000035':'''Spectacolul apare deoarece lumina Soarelui străbate o porțiune mai lungă a atmosferei când astrul se află aproape de orizont. Albastrul este împrăștiat din direcția privirii pe acest drum mai lung, iar roșul și portocaliul, cu lungimi de undă mai mari, ajung să domine cerul. Praful, poluarea și vaporii de apă pot accentua efectul, producând culori și mai vii. Norii au și ei un rol important: reflectă și refractă lumina colorată, sporind adesea frumusețea priveliștii. Nuanțele și intensitatea unui răsărit sau apus depind de condițiile atmosferice ale fiecărei zile. Umiditatea, temperatura și aerosolii contribuie la caracterul unic al fiecărui spectacol. De aceea, două răsărituri sau apusuri nu arată niciodată exact la fel și îi fascinează mereu pe cei care privesc cerul.''',
't000036':'''Odată cu anotimpurile se schimbă și aspectul cerului. Variațiile sezoniere ale culorii sunt mai puternice în regiunile temperate și mai puțin vizibile în apropierea ecuatorului, unde diferențele dintre anotimpuri sunt mici. Vara aduce de obicei ceruri de un albastru mai adânc, datorită umidității mai scăzute și aerului mai curat. Zilele lungi lasă mai mult timp încălzirii atmosferei, favorizând apariția după-amiaza a norilor cumulus pufoși, caracteristici vremii frumoase. Soarele aflat mai sus în cer face lumina să străbată mai puțină atmosferă, intensificând albastrul. Toamna, cerul devine adesea mai limpede pe măsură ce umiditatea scade. Unghiul mai mic al Soarelui poate aduce apusuri mai colorate, cu lumina oblică în nuanțe calde și bogate.''',
't000037':'''Schimbările vremii din toamnă pot aduce și formațiuni de nori mai variate, îmbogățind peisajul cerului. Iarna are propriile trăsături. Aerul rece și uscat poate produce un cer foarte limpede, de un albastru intens, mai ales în zilele senine și răcoroase. În unele regiuni, iarna aduce însă mai mulți nori și precipitații, astfel încât cerul variază de la albastru strălucitor la gri uniform. Primăvara vestește alte transformări: schimbarea tiparelor vremii aduce un amestec de cer senin și nori spectaculoși. Nivelul mai mare de polen poate crea uneori o ușoară pâclă. Pe măsură ce temperaturile cresc, norii cumulus apar mai des, semnalând apropierea condițiilor de vară.''',
't000038':'''Aceste schimbări nu sunt doar plăcute privirii; ele oferă informații despre starea atmosferei, vreme și trecerea anotimpurilor. Observându-le, înțelegem mai bine interacțiunea complexă dintre lumina solară, compoziția aerului și fenomenele meteorologice care schimbă neîncetat tabloul cerului. Studiul răsăriturilor, apusurilor și variațiilor sezoniere depășește aprecierea estetică. El oferă indicii despre optica atmosferică, tiparele climatice și chiar calitatea aerului. Apusurile deosebit de vii pot semnala uneori particule în atmosfera superioară, provenite din erupții vulcanice, incendii mari sau alte evenimente importante. Cunoașterea acestor fenomene are și aplicații practice. Agricultorii, marinarii și oamenii care petrec timp afară au folosit multă vreme cerul pentru a anticipa vremea.''',
't000039':'''Vechea zicală engleză „Cer roșu seara, marinarul se bucură; cer roșu dimineața, marinarul se îngrijorează” se bazează pe faptul că sistemele meteorologice se deplasează, în general, de la vest la est la latitudinile mijlocii. Un cer roșu la apus, spre vest, sugerează adesea apropierea vremii senine, în timp ce roșul de la răsărit, spre est, poate arăta că vremea bună a trecut și se apropie furtuni. În lumea de astăzi, când petrecem mult timp în interior, observarea acestor fenomene ne poate reconecta cu ritmurile naturale ale planetei. Ele ne amintesc de frumusețea și complexitatea atmosferei Pământului și de locul nostru în acest sistem dinamic. În fața problemelor de mediu și a schimbărilor climatice, studiul culorilor cerului și al variațiilor lor devine tot mai important.''',
't000040':'''Schimbările tiparelor obișnuite sau ale intensității culorilor pot indica transformări atmosferice mai ample și pot furniza date utile cercetătorilor climei și mediului. Spectacolul răsăriturilor, apusurilor și cerurilor sezoniere oferă, așadar, nu numai frumusețe, ci și o fereastră spre mecanismele complexe ale atmosferei. Înțelegând și apreciind aceste fenomene, aflăm mai multe despre mediu și despre locul nostru în el și ne reamintim cât de important este să păstrăm echilibrul delicat al atmosferei pentru generațiile viitoare.''',
't000041':'Capitolul al cincilea — Poluarea atmosferică și culoarea cerului'
}
seen=set()
for n in (5,6):
 f=p/f'{n:04}.json';d=json.loads(f.read_text())
 for x in d['segments']:
  assert not x['translation'] and x['id'] in t;x['translation']=t[x['id']];seen.add(x['id'])
 f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
assert seen==set(t)
print('Translated',len(seen))
